const router = express.Router();

// Google OAuth routes
router.get('/google', passport.authenticate('google', { scope: ['profile', 'email'] }));

router.get('/google/callback',
  passport.authenticate('google', { failureRedirect: '/login' }),
  (req, res) => {
    // Successful authentication, redirect to frontend

const frontendUrl = process.env.REACT_APP_API_URL?.replace('/api', '') || 'http://localhost:3000';
    res.redirect(`${frontendUrl}/auth/callback`);
  }
);

// Session endpoint - returns current user info
router.get('/session', (req, res) => {
  if (req.isAuthenticated()) {

const user = req.user;
    res.json({
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        image: user.image
      }
    });
  } else {
    res.status(401).json({ error: 'Not authenticated' });
  }
});

// Login endpoint for testing (creates a mock user)
router.post('/login', (req, res, next) => {
  // For testing purposes, create a test user if not exists
  const { User } = require('../models');

  if (req.body.testUser) {
    // Create or find a test user
    User.findOrCreate({
      where: { email: 'testuser@example.com' },
      defaults: {
        name: 'Test User',
        email: 'testuser@example.com',
        image: null
      }
    }).then(([user]) => {
      req.login(user, (err) => {
        if (err) {
          return res.status(500).json({ error: 'Login failed' });
        }
        return res.json({
          user: {
            id: user.id,
            name: user.name,
            email: user.email,
            image: user.image
          }
        });
      });
    }).catch(next);
  } else {
    res.status(400).json({ error: 'Invalid request' });
  }
});

// Logout endpoint
router.post('/logout', (req, res) => {
  req.logout((err) => {
    if (err) {
      return res.status(500).json({ error: 'Logout failed' });
    }
    req.session.destroy((err) => {
      if (err) {
        return res.status(500).json({ error: 'Session destruction failed' });
      }
      res.json({ message: 'Logged out successfully' });
    });
  });
});

module.exports = router;

