const { Board, User } = require('../models');

function isAuthenticated(req, res, next) {
  if (req.isAuthenticated()) {
    return next();
  }
  res.status(401).json({ error: 'Not authenticated' });
}

// Get all boards for the current user
router.get('/boards', isAuthenticated, async (req, res) => {
  try {

const boards = await Board.findAll({
      where: { ownerId: req.user.id },
      order: [['updatedAt', 'DESC']]
    });
    res.json(boards);
  } catch (error) {
    console.error('Error fetching boards:', error);
    res.status(500).json({ error: 'Failed to fetch boards' });
  }
});

// Create a new board
router.post('/boards', isAuthenticated, async (req, res) => {
  try {

const board = await Board.create({
      id: boardId,
      name: req.body.name || 'Untitled Board',
      objects: [],
      ownerId: req.user.id
    });
    res.status(201).json({ boardId: board.id });
  } catch (error) {
    console.error('Error creating board:', error);
    res.status(500).json({ error: 'Failed to create board' });
  }
});

// Save board state
router.post('/boards/:boardId', isAuthenticated, async (req, res) => {
  try {
    const { boardId } = req.params;
    const { objects } = req.body;

const board = await Board.findOne({ where: { id: boardId } });

    if (!board) {
      return res.status(404).json({ error: 'Board not found' });
    }

    board.objects = objects || [];
    await board.save();

    res.json({ success: true, boardId: board.id });
  } catch (error) {
    console.error('Error saving board:', error);
    res.status(500).json({ error: 'Failed to save board' });
  }
});

// Load board state
router.get('/boards/:boardId', isAuthenticated, async (req, res) => {
  try {
    const { boardId } = req.params;

const board = await Board.findOne({ where: { id: boardId } });

    if (!board) {
      return res.status(404).json({ error: 'Board not found' });
    }

    res.json({
      boardId: board.id,
      objects: board.objects || [],
      updatedAt: board.updatedAt.toISOString()
    });
  } catch (error) {
    console.error('Error loading board:', error);
    res.status(500).json({ error: 'Failed to load board' });
  }
});

// Delete a board
router.delete('/boards/:boardId', isAuthenticated, async (req, res) => {
  try {
    const { boardId } = req.params;

const board = await Board.findOne({ 
      where: { id: boardId, ownerId: req.user.id } 
