const io = new Server(server, {
    cors: {
      origin: process.env.REACT_APP_API_URL || 'http://localhost:3000',
      methods: ['GET', 'POST'],
      credentials: true
    }
  });

  // Authentication middleware for Socket.io
  io.use((socket, next) => {

const user = socket.handshake.auth.user;

    if (user) {
      // Use pre-authenticated user data
      socket.user = user;
      return next();
    }

    if (token) {
      // Verify JWT token
      jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
        if (err) {
          return next(new Error('Authentication error'));
        }
        socket.user = decoded;
        next();
      });
    } else {
      // Allow anonymous connections for testing
      socket.user = {
        id: socket.id,
        name: `User ${socket.id.substr(0, 6)}`,
        isAnonymous: true
      };
      next();
    }
  });

  io.on('connection', (socket) => {
    console.log(`User connected: ${socket.id}`, socket.user);

    // Join a room (board)
    socket.on('joinRoom', (data) => {
      const { boardId } = data;

const roomName = `board:${boardId}`;

      // Leave any previous rooms
      socket.rooms.forEach(room => {
        if (room !== socket.id && room.startsWith('board:')) {
          socket.leave(room);
        }
      });

      // Join the new room
      socket.join(roomName);
      socket.boardId = boardId;

      // Initialize room if not exists
      if (!rooms.has(roomName)) {
        rooms.set(roomName, {
          users: new Map(),
          objects: []
        });
      }

const room = rooms.get(roomName);

      // Add user to room
      room.users.set(socket.id, {
        id: socket.user.id,
        name: socket.user.name || socket.user.email || 'Anonymous',
        socketId: socket.id,
        cursor: null
      });

      // Send current room state to the joining user
      socket.emit('stateRestored', { objects: room.objects });

      // Broadcast updated user list to all in room

const users = Array.from(room.users.values());
      io.to(roomName).emit('roomUsers', { users });

      console.log(`User ${socket.user.name} joined room ${boardId}`);
    });

    // Handle cursor movement
    socket.on('cursorMove', (data) => {
      const { x, y } = data;

const user = room.users.get(socket.id);

        if (user) {
          user.cursor = { x, y };

          // Broadcast cursor position to other users in the room
          socket.to(roomName).emit('cursorUpdate', {
            userId: socket.user.id,
            name: user.name,
            x,
            y
          });
        }
      }
    });

    // Handle drawing events
    socket.on('draw', (data) => {

const room = rooms.get(roomName);

        // Store the drawing in room state
        room.objects.push({
          ...data,
          id: data.id || `line_${Date.now()}`,
          userId: socket.user.id
        });

        // Broadcast to other users in the room
        socket.to(roomName).emit('drawUpdate', {
          ...data,
          userId: socket.user.id
        });
      }
    });

    // Handle object addition (shapes like rectangles)
    socket.on('addObject', (data) => {

const newObject = {
          ...data,
          id: objectId,
          userId: socket.user.id
        };

        // Store the object in room state
        room.objects.push(newObject);

        // Broadcast to other users in the room
        socket.to(roomName).emit('objectAdded', newObject);
      }
    });

    // Handle undo action
    socket.on('undo', (data) => {
      console.log(`Undo requested for board ${socket.boardId} by ${socket.user.id}`);

const lastObject = userObjects[userObjects.length - 1];

          // Remove from room state
          room.objects = room.objects.filter(obj => obj.id !== lastObject.id);

          // Broadcast to all users in the room
          io.to(roomName).emit('objectRemoved', {
            objectId: lastObject.id,
            userId: socket.user.id
          });
        }
      }
    });

    // Handle redo action
    socket.on('redo', (data) => {

const room = rooms.get(roomName);

        // Check if there's a removed object to restore
        if (data.restoredObject) {
          room.objects.push(data.restoredObject);

          // Broadcast to other users
          socket.to(roomName).emit('objectAdded', data.restoredObject);
        }
      }
    });

    // Handle clear board
    socket.on('clear', (data) => {

const room = rooms.get(roomName);

        // Clear objects from this user only
        room.objects = room.objects.filter(obj => obj.userId !== socket.user.id);

        // Broadcast clear to all users
        io.to(roomName).emit('boardCleared', { userId: socket.user.id });
      }
    });

    // Handle disconnection
    socket.on('disconnect', () => {
      console.log(`User disconnected: ${socket.id}`);

      // Remove user from their room
      if (socket.boardId) {

const room = rooms.get(roomName);
          room.users.delete(socket.id);

          // Broadcast updated user list

const users = Array.from(room.users.values());
          io.to(roomName).emit('roomUsers', { users });

          // Clean up empty rooms
          if (room.users.size === 0) {
            // Keep room data for 30 minutes
            setTimeout(() => {

const r = rooms.get(roomName);
              if (r && r.users.size === 0) {
                rooms.delete(roomName);
              }
            }, 30 * 60 * 1000);
          }
        }
      }
    });
  });

  return io;
}

