import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Stage, Layer, Line, Rect, Circle } from 'react-konva';
import Cursor from './Cursor';

const Canvas = ({
  objects,
  currentUserId,
  currentTool,
  currentColor,
  brushSize,
  onDraw,
  onAddObject,
  onCursorMove
}) => {

const currentLine = useRef(null);
  const [dimensions, setDimensions] = useState({ width: window.innerWidth - 220, height: window.innerHeight - 140 });

  useEffect(() => {

const handleResize = () => {
      setDimensions({
        width: window.innerWidth - 220,
        height: window.innerHeight - 140
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

const pos = stage.getPointerPosition();

    if (currentTool === 'pen') {
      isDrawing.current = true;
      currentLine.current = {
        type: 'line',
        points: [pos.x, pos.y],
        color: currentColor,
        brushSize: brushSize
      };
    } else if (currentTool === 'rectangle') {
      // Create rectangle immediately on click
      onAddObject({
        type: 'rectangle',
        x: pos.x,
        y: pos.y,
        width: 100,
        height: 80,
        fill: currentColor
      });
    }
  }, [currentTool, currentColor, brushSize, onAddObject]);

const pos = stage.getPointerPosition();

    // Send cursor position
    onCursorMove(pos.x, pos.y);

    if (!isDrawing.current || currentTool !== 'pen') return;

    if (currentLine.current) {

const newPoints = [...currentLine.current.points, pos.x, pos.y];
      currentLine.current = {
        ...currentLine.current,
        points: newPoints
      };

      // Force re-render
      stageRef.current.batchDraw();
    }
  }, [currentTool, onCursorMove]);

const handleMouseUp = useCallback(() => {
    if (isDrawing.current && currentLine.current && currentLine.current.points.length > 2) {
      onDraw(currentLine.current);
    }
    isDrawing.current = false;
    currentLine.current = null;
  }, [onDraw]);

const renderObject = (obj, index) => {
    if (obj.type === 'line') {
      return (
        <Line
          key={obj.id || index}
          points={obj.points}
          stroke={obj.color}
          strokeWidth={obj.brushSize}
          lineCap="round"
          lineJoin="round"
          tension={0.5}
        />
      );
    } else if (obj.type === 'rectangle') {
      return (
        <Rect
          key={obj.id || index}
          x={obj.x}
          y={obj.y}
          width={obj.width}
          height={obj.height}
          fill={obj.fill}
          stroke={obj.fill}
          strokeWidth={2}
        />
      );
    }
    return null;
  };

  return (
    <div className="canvas-container">
      <Stage
        ref={stageRef}
        width={dimensions.width}
        height={dimensions.height}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        className="konva-stage"
      >
        <Layer>
          {/* Existing objects */}
          {objects.map((obj, index) => renderObject(obj, index))}

          {/* Current drawing line */}
          {isDrawing.current && currentLine.current && (
            <Line
              points={currentLine.current.points}
              stroke={currentLine.current.color}
              strokeWidth={currentLine.current.brushSize}
              lineCap="round"
              lineJoin="round"
              tension={0.5}
            />
          )}
        </Layer>
      </Stage>
    </div>
  );
};

