// Simple hash function for generating consistent color index

function hashCode(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {

const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash);
}

